document.addEventListener("DOMContentLoaded",()=>{const a={facts:[["Location","Prayagraj, Uttar Pradesh","Allahabad Fort stands near the sacred Triveni Sangam region."],["Builder","Emperor Akbar","The issue asks to present it as one of the grandest forts built by Emperor Akbar."],["Architecture","Mughal Architecture","The fort is framed through Mughal planning, scale, gateways, walls and imperial presence."],["Sacred context","Triveni Sangam","Its location on the banks of the Triveni Sangam gives it cultural and spiritual importance."],["Key attractions","Ashoka Pillar + Patalpuri Temple","The issue specifically asks to include the Ashoka Pillar and Patalpuri Temple."],["Explorer focus","History + heritage","This page covers overview, history, builder, Mughal architecture, Sangam, pillar, temple, facts and gallery."]],sections:{history:[["Akbar's imperial fort","Allahabad Fort was built under Emperor Akbar as a major Mughal stronghold near the Sangam."],["Strategic river location","Its position near the meeting of rivers made the site valuable for movement, control and symbolism."],["Layered heritage","The fort area combines Mughal history, ancient inscriptions, religious spaces and later heritage memory."],["Modern landmark","Today it remains one of Prayagraj's most important heritage landmarks, though access may be restricted in parts."]],builder:[["Emperor Akbar","Akbar's builder story links the fort with Mughal imperial ambition, administration and architecture."],["Mughal planners","The fort reflects large-scale planning suited to riverfront defence and ceremonial authority."],["Imperial administration","Its location helped connect political power with a deeply symbolic sacred geography."],["Artisans and engineers","The massive walls, gateways and internal structures depended on skilled builders and planners."]],architecture:[["Massive ramparts","High defensive walls and bastions give the fort its grand Mughal military character."],["Riverfront planning","The fort uses the river setting as part of its geography, visibility and defensive logic."],["Imperial scale","Large spaces, gateways and walls communicate Mughal power and ordered planning."],["Layered structures","Religious, historic and military elements coexist within the broader fort story."]],sangam:[["Sacred confluence","Triveni Sangam is traditionally understood as the meeting point of the Ganga, Yamuna and Saraswati."],["Cultural setting","The fort's location gives it a rare combination of imperial and spiritual significance."],["Pilgrim landscape","Prayagraj's Sangam area is central to religious gatherings, rituals and cultural memory."],["Strategic visibility","The riverfront setting also helped the fort monitor movement and routes."]],pillar:[["Ashoka Pillar","The Ashoka Pillar connects the fort site with much older Mauryan-era heritage."],["Inscription value","Ancient inscriptions make the pillar an important source for historical learning."],["Layered timeline","The pillar shows how the site contains histories older than the Mughal fort itself."],["Heritage responsibility","Visitors should treat inscriptions and historic stone surfaces with care."]],temple:[["Patalpuri Temple","The issue asks to include Patalpuri Temple as a major heritage attraction inside the fort context."],["Sacred layer","The temple adds religious significance to the fort's political and architectural story."],["Akshayavat memory","Patalpuri Temple is often discussed with the sacred Akshayavat tradition in Prayagraj heritage."],["Living heritage","The fort landscape is not only architectural; it also carries ongoing faith and memory."]]},points:[["gate","Fort gateway",43,70,"Entry control","Mughal gateways guided entry and strengthened defensive control."],["wall","Massive ramparts",35,52,"Mughal Architecture","Walls and bastions communicate imperial scale and military planning."],["sangam","Triveni Sangam edge",66,36,"Sacred geography","The river confluence gives the fort cultural and spiritual depth."],["pillar","Ashoka Pillar point",54,47,"Ancient heritage","Represents older inscriptions and Mauryan-era historical layers."],["temple","Patalpuri Temple zone",58,62,"Sacred attraction","Adds a religious heritage layer inside the fort story."],["view","Riverfront viewpoint",72,58,"Landscape view","Explains how riverfront geography shaped visibility and strategy."]],gallery:[["Mughal fort walls","../../assets/heritage_forts.png","Visual placeholder for Allahabad Fort's grand ramparts and military scale."],["Triveni Sangam context","../../assets/travel_rivers.png","The Sangam setting gives the fort cultural and spiritual importance."],["Ashoka Pillar heritage","../../assets/heritage_monuments.png","Ancient pillar heritage adds a deeper timeline to the fort story."],["Sacred architecture","../../assets/heritage_temples.png","Patalpuri Temple adds faith and living heritage to the explorer."]],interesting:[["Mughal and sacred together","Imperial architecture and sacred geography meet in one place."],["Older than Akbar's fort","The Ashoka Pillar reminds visitors that the site contains much older historical layers."],["River strategy","Rivers made the location important for movement, defence, trade and symbolism."],["Layered learning","One page can teach Mughal architecture, Mauryan inscriptions, pilgrimage geography and temple tradition."]],faqs:[["What is Allahabad Fort famous for?","It is famous as a grand Mughal fort built by Emperor Akbar near the Triveni Sangam."],["Who built Allahabad Fort?","The issue frames Allahabad Fort as one of the grandest forts built by Emperor Akbar."],["Why is Triveni Sangam important here?","The fort stands near the sacred confluence, giving it spiritual and geographic importance."],["What are key attractions?","The issue specifically asks to include Ashoka Pillar and Patalpuri Temple."],["What does this explorer cover?","Overview, history, builder, Mughal architecture, Triveni Sangam, Ashoka Pillar, Patalpuri Temple, facts, gallery and landing integration."]]},e=a=>String(a).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;"),t=a=>document.getElementById(a);function r(a,t,r){return`<article class="${t}"><span>0${r+1}</span><h3>${e(a[0])}</h3><p>${e(a[1])}</p></article>`}function i(r){const i=a.points.find(a=>a[0]===r)||a.points[0];document.querySelectorAll(".map-pin").forEach(a=>a.classList.toggle("active",a.dataset.point===i[0])),t("map-info").innerHTML=`<span>${e(i[4])}</span><h3>${e(i[1])}</h3><p>${e(i[5])}</p>`}t("facts-grid").innerHTML=a.facts.map(a=>`<article class="fact-card"><span>${e(a[0])}</span><strong>${e(a[1])}</strong><p>${e(a[2])}</p></article>`).join(""),Object.keys(a.sections).forEach(e=>{t(`${e}-grid`).innerHTML=a.sections[e].map((a,t)=>r(a,`${e}-card`,t)).join("")}),t("interesting-grid").innerHTML=a.interesting.map((a,e)=>r(a,"interesting-card",e)).join(""),t("faq-list").innerHTML=a.faqs.map(a=>`<details class="faq-item"><summary>${e(a[0])}</summary><p>${e(a[1])}</p></details>`).join(""),t("map-pins").innerHTML=a.points.map((a,t)=>`<button class="map-pin" type="button" data-point="${e(a[0])}" style="left:${a[2]}%;top:${a[3]}%" aria-label="${e(a[1])}">${t+1}</button>`).join(""),document.querySelectorAll(".map-pin").forEach(a=>a.addEventListener("click",()=>i(a.dataset.point))),t("gallery-grid").innerHTML=a.gallery.map(a=>`<article class="gallery-card"><img src="${e(a[1])}" alt="${e(a[0])}" onerror="this.src='../../assets/hero_banner.png'"><div><h3>${e(a[0])}</h3><p>${e(a[2])}</p></div></article>`).join(""),i(a.points[0][0]),window.AllahabadFortExplorer={facts:()=>[...a.facts],points:()=>[...a.points],faqs:()=>[...a.faqs]}});